class TestRouterRegistration:
    def test_register_node_adds_to_registry(self, router):
        r, mock_registry = router
        r.register_node(node_id=1, address="10.0.0.1:8080")
        mock_registry.add.assert_called_once_with(1, "10.0.0.1:8080")

    def test_unregister_node_removes_from_registry(self, router):
        r, mock_registry = router
        r.unregister_node(node_id=1)
        mock_registry.remove.assert_called_once_with(1)

    def test_register_duplicate_node_raises_error(self, router):
        r, mock_registry = router
        mock_registry.add.side_effect = ValueError("Node already exists")
        with pytest.raises(ValueError):
            r.register_node(node_id=1, address="10.0.0.1:8080")

class TestRouterMessageForwarding:
    def test_route_message_to_known_node(self, router):
        r, mock_registry = router
        mock_registry.get.return_value = "10.0.0.1:8080"
        result = r.route_message(target_node_id=1, message={"data": "test"})
        assert result is True

    def test_route_message_to_unknown_node_raises_error(self, router):
        r, mock_registry = router
        mock_registry.get.return_value = None
        with pytest.raises(KeyError):
            r.route_message(target_node_id=999, message={"data": "test"})

    def test_broadcast_message_sends_to_all_nodes(self, router):
        r, mock_registry = router
        mock_registry.get_all.return_value = {1: "10.0.0.1:8080", 2: "10.0.0.2:8080"}
        results = r.broadcast_message(message={"data": "test"})
        assert len(results) == 2
        assert all(results.values())

class TestRouterHealth:
    def test_router_health_check_returns_status(self, router):
        r, _ = router
        health = r.health_check()
        assert health["status"] == "healthy"
        assert "latency_ms" in health
        assert "active_routes" in health

    def test_router_health_check_reports_unhealthy_when_registry_down(self, router):
        r, mock_registry = router
        mock_registry.is_healthy.return_value = False
        health = r.health_check()
        assert health["status"] == "degraded"